const catalogs: Record<AppLocale, Dict> = {
  en: { ...en },
  zh: { ...en, ...zhUi },
};

export function t(locale: AppLocale | string | undefined, key: string, params?: Record<string, string | number>): string {
  const lang: AppLocale = locale === "en" ? "en" : "zh";
  let text = catalogs[lang][key] ?? catalogs.en[key] ?? key;
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      text = text.replace(new RegExp("\\{" + k + "\\}", "g"), String(v));
    }
  }
  return text;
}

export function resolveLocale(raw: unknown): AppLocale {
  const value = String(raw || "").trim().toLowerCase();
  if (value === "en" || value === "en-us" || value === "english") return "en";
  return "zh";
}
